  public Player start()
  {
    // Initialize board from configuration
    Configuration config = getConfiguration();
    Piece[][] initialBoard = config.getInitialBoard();
    int size = config.getSize();
    setBoard(new Piece[size][size]);
    for (int x = 0; x < size; x++) {
      for (int y = 0; y < size; y++) {
        getBoard()[x][y] = initialBoard[x][y];
      }
    }
    
    // Set central place in configuration
    Place centralPlace = Pa20Factory.eINSTANCE.createPlace();
    centralPlace.setX(size / 2);
    centralPlace.setY(size / 2);
    config.setCentralPlace(centralPlace);
    
    // Set initial current player (first player)
    EList<Player> players = config.getPlayers();
    if (players.isEmpty()) {
      return null;
    }
    setCurrentPlayer(players.get(0));
    setNumMoves(0);
    
    // Game loop
    while (true) {
      refreshOutput();
      
      // Get available moves for current player
      EList<Move> availableMoves = getAvailableMoves(getCurrentPlayer());
      
      // If no available moves, game ends, winner decided by score
      if (availableMoves.isEmpty()) {
        Player winner = getCurrentPlayer();
        for (Player p : players) {
          if (p.getScore() > winner.getScore()) {
            winner = p;
          }
        }
        return winner;
      }
      
      // Prompt player for move
      Move move = getCurrentPlayer().nextMove(this, availableMoves);
      
      // Execute move
      movePiece(move);
      setNumMoves(getNumMoves() + 1);
      
      // Update score
      Piece piece = getPiece(move.getSource());
      updateScore(getCurrentPlayer(), piece, move);
      
      // Check winner
      Player winner = getWinner(getCurrentPlayer(), piece, move);
      if (winner != null) {
        refreshOutput();
        return winner;
      }
      
      // Switch to next player
      int currentIndex = players.indexOf(getCurrentPlayer());
      int nextIndex = (currentIndex + 1) % players.size();
      setCurrentPlayer(players.get(nextIndex));
    }
  }

