  public Player getWinner(final Player lastPlayer, final Piece lastPiece, final Move lastMove)
  {
    // Check if protection is active
    Configuration config = getConfiguration();
    if (getNumMoves() < config.getNumMovesProtection()) {
      return null;
    }
    
    Place source = lastMove.getSource();
    Place destination = lastMove.getDestination();
    Place centralPlace = config.getCentralPlace();
    
    // Condition 1: A Knight leaves the central square
    if (lastPiece instanceof Knight) {
      if (source.getX() == centralPlace.getX() && source.getY() == centralPlace.getY()) {
        if (destination.getX() != centralPlace.getX() || destination.getY() != centralPlace.getY()) {
          return lastPlayer;
        }
      }
    }
    
    // Condition 2: Only one player's pieces remain on the board
    EList<Player> players = config.getPlayers();
    int playersWithPieces = 0;
    Player lastPlayerWithPieces = null;
    for (Player p : players) {
      boolean hasPieces = false;
      for (int x = 0; x < config.getSize(); x++) {
        for (int y = 0; y < config.getSize(); y++) {
          Piece piece = getBoard()[x][y];
          if (piece != null && piece.getPlayer() == p) {
            hasPieces = true;
            break;
          }
        }
        if (hasPieces) break;
      }
      if (hasPieces) {
        playersWithPieces++;
        lastPlayerWithPieces = p;
      }
    }
    
    if (playersWithPieces == 1) {
      return lastPlayerWithPieces;
    }
    
    return null;
  }

